package android.app; public class Service {public static final int START_NOT_STICKY=2,STOP_FOREGROUND_REMOVE=1; public boolean failStart; public int foregroundStarts,foregroundStops,selfStops; public void onCreate(){} public void onDestroy(){} public int onStartCommand(android.content.Intent i,int f,int s){return 2;} public android.os.IBinder onBind(android.content.Intent i){return null;} public <T>T getSystemService(Class<T> c){return c.cast(new NotificationManager());} public void startForeground(int id,Notification n){if(failStart)throw new SecurityException("simulated FGS denial");foregroundStarts++;} public void stopForeground(int f){foregroundStops++;} public void stopSelf(){selfStops++;}}